def public_item(item: dict) -> dict:
    return {k:v for k,v in item.items() if k not in {"answer","explanation"}}


def check_item(item: dict, value: str) -> bool | None:
    if item["type"] in {"open","self_report"}:
        return None
    expected = str(item["answer"]).strip().casefold()
    answer = str(value).strip().replace(",", ".").casefold()
    return answer == expected
